DEFAULT_D,DEFAULT_R,DEFAULT_G=F(1,10**8),F(1,10**11),F(1,60)
DEFAULT_CUT=17

DMAX,RMAX=F(1,12),F(1,3000)
POLYNOMIALS={
 'carrier_ratio':(1,-4,0),
 'shallow_C_minus_1_t':(6,-49,-70),
 'shallow_C_minus_k':(42,0,-35),
 'pure3_maximizing_cell':(3,-23,3),
 'root0_below_root1_reference':(2,-7,-1),
 'first_cell_below_reference':(4,-5,-3),
 'other_cells_below_reference':(1,-1,-1),
}
def require(ok,msg):
 if not ok:raise ValueError(msg)
def rational(x):
 require(type(x)in(int,str,F),'Exact rational input, not binary float or boolean')
 return F(x)
def encode(x):
 if isinstance(x,F):return str(x)
 if isinstance(x,dict):return {str(k):encode(v)for k,v in x.items()}
 if isinstance(x,(list,tuple)):return [encode(v)for v in x]
 return x

def face_geometry():
 eta=(F(1,18),)+(F(1,9),)*4
 pre=[[F(0),F(1,5)if c<2 else F(0),F(0)if c==2 else F(1,5),F(3,20)if c<2 else F(1,10),F(1,5)]for c in range(5)]
 return tuple(eta[c]*pre[c][s]for c in range(5)for s in range(5)),(F(1,36),F(1,12),F(5,36))

def parameters(d,R,gap=None):
 d,R=rational(d),rational(R)
 require(0<=d<=DMAX and 0<R<=RMAX,'Certified domain0<=d<=1/12,0<R<=1/3000')
 r=5*R;U=d/(1-d);Delta=U/4;A=3*d/(4*(3-2*d))
 h1=F(1,3)-d/18;eta=F(1,9)-d/18;hbar=F(1,2)+d/18;h0=F(1,6)+d/18
 z=F(3,4)+d/4;floor=F(1,4)-3*d/4
 require(d<F(1,2) and A<=Delta<F(1,18) and z<F(4,5)and floor>F(1,20),'106/153/156 source concentration and general117 forcing')
 require(h1>h0>0 and eta>0 and h1-h0>F(1,9),'117 actual root/first-beta guards')
 gaps=(F(1,10)-r,h1/5-r,eta/5-r,h1*(F(1,10)-A)-2*r,(F(1,6)-d/9)/5-r)
 endpoint=(F(59,600),F(173,2700),F(53,2700),F(16367,734400),F(161,5400))
 require(all(a>=b>0 for a,b in zip(gaps,endpoint)),'Five decreasing packing guards bounded at the certified rectangle endpoint')
 natural_gap=min(gaps)
 G=natural_gap if gap is None else rational(gap)
 require(0<G<=natural_gap and R/G<F(1,5),'Positive certified common gap and untruncated wrong-slot triangle')
 poly={name:F(a)+b*d+c*d*d for name,(a,b,c)in POLYNOMIALS.items()}
 deriv={name:max(F(b),F(b)+2*c*DMAX)for name,(a,b,c)in POLYNOMIALS.items()}
 lower={name:F(a)+b*DMAX+c*DMAX**2 for name,(a,b,c)in POLYNOMIALS.items()}
 require(all(deriv[k]<=0 and poly[k]>=lower[k]>0 for k in poly),'Every original interval polynomial decreases and stays positive')
 denominators={'1-d':1-d,'1-4d':1-4*d,'8-15d':8-15*d,'3-2d':3-2*d,'1/5-3d/8':F(1,5)-3*d/8}
 require(min(denominators.values())>0 and 6*d-23<0,'All ratio denominators and remaining quadratic derivative')
 v0=min(F(1,20),Delta+2*r);v1=min(F(1,10),Delta+r/h1)
 require(v0==Delta+2*r<=F(43,1650)<F(1,20) and v1==Delta+r/h1<=F(2171,78100)<F(1,10),'Monotone Q increments; both clips are inactive on the certified rectangle')
 require(F(3,20)+v0<=F(1,5) and F(1,10)+v1<=F(1,5),'Original factorial pre-cap bound')
 t=2*(1+d)/(1-4*d);C=(F(3,4)+d/4)/(F(1,5)-3*d/8);k=(6-d)/(3-2*d)
 require(C-1-t==poly['shallow_C_minus_1_t']/((8-15*d)*(1-4*d))>0,'Cbar dominates1+tbar')
 require(C-k==(42+68*d-35*d*d)/((8-15*d)*(3-2*d))>0 and k==h1/(h1-h0),'Cbar dominateskbar; same root-spill ratio')
 increments=((3+d)*U/72,d/36,U/12)
 root0=F(1,9)+increments[0]+increments[1];root1=F(5,36)+U/12;maxn=F(1,12)+d/36
 require(root1-root0==(1-d)/36+(3-d)*U/72>0,'General157 root mass dominance')
 require(maxn-(F(1,36)+increments[0])==poly['first_cell_below_reference']/(72*(1-d))>0,'General157 first cell dominance')
 require(maxn-(F(1,18)+U/36)==poly['other_cells_below_reference']/(36*(1-d))>0,'General157 other cell dominance')
 c=(F(7,10)+d/4,F(2,5)+13*d/90,F(4,15)+d/15,F(4,45)+d/45)
 H=(F(1,20)+21*d/20-d*d/5,F(1,10)+(19*d+2*d*d)/90,F(1,15)+d/9,F(1,45)+d/30-d*d/360)
 safeH=(F(1,20),F(1,10)-4*d/45,(1-d)/15,(1-d)/45)
 require(min(c+H+safeH)>0 and F(1,30)-4*d/45>=F(7,270),'Old complete tail envelopes and231 monotone min-envelopes')
 marker=F(3,5)-18*F(13,1215)
 require(marker==F(11,27)>0,'Original fixed-support marker coefficient')
 price=max(hbar/(5*G),F(65,9))
 require(price>=max(F(1),hbar/(5*G)) and price>=5*F(13,9),'169 heavy motion and marker use one actual residual')
 exposed={'old_Z':(1-d)*F(3,280)-F(1,420),'old_pair':(1-d)*F(13,180)-F(1,36),'four_projection_Z':(1-d)/168-F(1,420),'six_projection_Z':(1-d)*F(23,5880)-F(29,44100)}
 require(min(exposed.values())>0 and (146+5*d)/10800<F(1,36),'156/158/208/231 exposed source-price criteria')
 face_caps,face_budgets=face_geometry();cap_inc=[]
 for i,cap in enumerate(face_caps):
  cell,slot=divmod(i,5);excluded=slot==0 or(slot==1 and cell>=2)or(slot==2 and cell==2)
  if excluded:
   require(cap==0,'Exact P/root1-A/first-beta-B exclusion');change=F(0)
  elif slot!=3:change=d/90 if cell==0 else F(0)
  else:change=d/90+v0/18 if cell==0 else v0/9 if cell==1 else v1/9
  cap_inc.append(change)
 caps=tuple(a+b for a,b in zip(face_caps,cap_inc));budgets=tuple(a+b for a,b in zip(face_budgets,increments))
 require(min(cap_inc+list(increments))>=0,'Nonnegative containing raw-polytope enlargement')
 par={'delta':d,'rho':R,'rbar':r,'h1min':h1,'v0':v0,'v1':v1,'gap':G,'tbar':t,'Cbar':C,'kbar':k,'budget_increments':increments,'c':c,'H':H}
 guards={'source_radius':d,'residual_radius':R,'actual_r_upper':r,'joint_source_Delta_upper':Delta,'source_z_upper':z,'availability_upper':A,'h1_lower':h1,'first_beta_eta_lower':eta,'h_upper':hbar,'five_actual_gap_lowers':gaps,'minimum_actual_gap':natural_gap,'common_wrong_slot_gap':G,'whole_interval_polynomial_lowers':poly,'heavy_residual_price_coefficient':price,'heavy_slot_movement_coefficient':F(13,9),'independent_r_cutoff':None}
 return {'parameters':par,'guards':guards,'raw_caps':caps,'raw_budgets':budgets,'cap_increments':tuple(cap_inc),'source_loss_upper':U,'maximum_certified_gap':natural_gap,'ratio_denominators':denominators,'interval_polynomial_derivative_uppers':deriv,'interval_polynomial_endpoint_lowers':lower,'exposed_price_gap_margins':exposed,'safe_tail_headrooms':safeH,'scope':'Pointwise195 source-parameter and containing-polytope generator over the certified small rectangle. No complete head, all-bank/pruning,52-cost or K conclusion.'}


def module(name,path):
 spec=importlib.util.spec_from_file_location(name,path)
 require(spec is not None and spec.loader is not None,'Loadable original provider')
 value=importlib.util.module_from_spec(spec);spec.loader.exec_module(value);return value


def tail_error_from_row(row,par,tail):
 """Reuse the once-priced raw vertices; combine seven prices before the max.

 The row must be a current230 result for this same parameter domain and fixed
 raw polytope. The caller owns that source binding; calculate establishes it
 by rebuilding every row from its original exact dual.
 """
 d,R,G=(F(par[k])for k in ('delta','rho','gap'))
 require(F(tail['delta'])==d,'One common row/tail source radius')
 require(set(row['primitive_prices'])==set(tail['primitive_additions']),'The same seven residual coordinates')
 joint={k:F(value)+F(tail['primitive_additions'][k])for k,value in row['primitive_prices'].items()}
 require(len(joint)==7 and min(joint.values())>=0,'Seven nonnegative combined residual prices')
 biggest=max(joint.values());source=F(row['combined_source_upper'])
 expected=((F(0),F(0)),(R/G,F(0)),(F(0),R/G))
 require(len(row['triangle_vertices'])==3,'All current230 domain vertices')
 results=[]
 for v,want in zip(row['triangle_vertices'],expected):
  q=tuple(map(F,v['q']));require(q==want,'The same complete source triangle')
  remain=R-G*sum(q);raw=F(v['signed_raw_transport'])
  require(remain>=0 and F(v['complete_row_error_upper'])==source+raw+remain*max(map(F,row['primitive_prices'].values())),
          'Source-bound row residual matches the current seven prices')
  shift=G*sum(F(a)*b for a,b in zip(tail['wrong_slot_prices_over_gap'],q))
  value=source+F(tail['intercept'])+raw+shift+remain*biggest-F(tail['face_tail'])
  results.append({'q':q,'residual_radius':remain,'signed_raw_transport':raw,'tail_wrong_slot_upper':shift,'row_and_tail_minus_face_tail_upper':value})
 return {'joint_primitive_prices':joint,'joint_residual_price':biggest,'triangle_vertices':results,
         'transport_error_upper':max(v['row_and_tail_minus_face_tail_upper']for v in results)}


def original_tests(heavy,survival):
 """Source-bind four objectives without inventing unavailable per-key labels."""
 tests=[]
 for r in heavy['heavy_results']:
  tests.append({'name':'heavy-'+str(r['index']),'source_bank':'heavy','coefficients':r['scan']['coefficients'],'scan':r['scan']})
 for name,r in [('AP13',survival['AP13_result']),('AP11-block0',survival['AP11_block_results'][0])]:
  require(r['hinge_coefficients']==r['scan']['coefficients'],'The same original survival coefficient vector')
  tests.append({'name':name,'source_bank':'survival','coefficients':r['hinge_coefficients'],'scan':r['scan']})
 require([t['name']for t in tests]==['heavy-0','heavy-16','AP13','AP11-block0'],'All four original tests')
 return tests


def calculate(base,delta=DEFAULT_D,rho=DEFAULT_R,gap=DEFAULT_G,cut=DEFAULT_CUT):
 require(PINS,'Final pinned source closure')
 domain=parameters(delta,rho,gap);par=domain['parameters'];caps,budgets=domain['raw_caps'],domain['raw_budgets']
 require(type(cut)is int and cut>=3,'A fixed legal cut in each original exponent family')
 io=module('small_bank_io',base/'certificate_io.py')
 read=lambda rel:json.loads(io.read_artifact_bytes(base/rel))
 heavy,survival=[read(io.named_artifact(base/'certificates/source_norms', name + '.json').relative_to(base).as_posix())for name in ('retained135125_heavy_comparison','retained135125_survival_comparison')]
 source_domain=read('certificates/source_norms/source-budgets/extended_source_bridge_comparison.json')
 pins=dict(PINS)
 for doc in (heavy,survival,source_domain):
  for path,pin in doc['source_sha256'].items():
   require(path not in pins or pins[path]==pin,'Consistent original source '+path);pins[path]=pin
 for path,pin in pins.items():
  require(sha256(io.read_artifact_bytes(base/path)).hexdigest()==pin,'Pinned logical source '+path)
 load=lambda name:module('small_bank_'+name,io.named_artifact(base/'frontier', name+'.py'))
 complete,partial,old,e5,exact,pair,bridge,tail_provider=[load(n)for n in ('complete_retained_row_transport','retained_pair_row_transport','joint_deletion_row_transport','selected_deletion_mask_row_transport','retained135_heavy_comparison','retained135125_heavy_comparison','k_face_common_seven_hinges','retained_punctured_tail_support')]
 tests=original_tests(heavy,survival)
 supports={t['name']:tail_provider.compile_tail_support(par['delta'],t['coefficients'],{'unpunctured':[cut]*4,'punctured':[cut]*4})for t in tests}
 require(all(F(t['scan']['maximizing_witness']['complete_tail_constant'])==supports[t['name']]['face_tail']for t in tests),'Every original complete face tail is subtracted exactly once')
 pre,rawface,density,descendant=bridge.source_tables(2);wi=[int(5*w)for row in density for w in row]
 require(face_geometry()==(tuple(v for row in rawface for v in row),bridge.GROUP_MASSES),'The exact original25-node face and its three groups')
 raw=load('joint_selected_source_comparison').RawSelectedLP(bridge)
 original=load('retained_deletion_heavy_comparison').RetainedDeletionLP(raw,wi)
 inventories=[];counts=[]
 for branch in ('nested','disjoint'):
  oldlp=exact.lp_class(base)(original,wi,pre,branch);lp=pair.lp_class(base)(original,wi,pre,descendant,branch)
  require(lp.specification()==heavy['branch_lps'][branch]==survival['branch_lps'][branch],'Original complete branch matrix')
  e5.check_row_meanings(oldlp,wi);inventory=(old.row_inventory(oldlp,wi),partial.new_inventory(lp,pre,descendant,wi))
  counts.append(complete.complete_inventory(lp,original,bridge,wi,*inventory));inventories.append(inventory)
 require(inventories[0]==inventories[1]and counts[0]==counts[1],'Both geometric alternatives have the same complete row inventory')
 # Certify the parameter generator against the original endpoint once. The
 # whole smaller domain is justified by the pointwise inequalities above.
 study=load('k_neighborhood_radius_study').Study(base)
 require(all(pins.get(path)==pin for path,pin in study.pins.items()),'Original source-domain proof closure')
 endpoint=parameters(DMAX,RMAX)
 oldpar,oldguards=study.get('extended_source_bridge_comparison').parameters_and_guards(study)
 require(endpoint['parameters']==oldpar and endpoint['guards']=={k:v for k,v in oldguards.items()if k!='domain_proof'},'Exact195 endpoint parameters and guards')
 require(encode(endpoint['raw_caps'])==source_domain['complete_heads']['uniform_caps']and encode(endpoint['raw_budgets'])==source_domain['complete_heads']['uniform_budgets'],'Exact195 endpoint containing polytope')
 invalid_rejections=0
 for d,r,g in ((F(-1),rho,gap),(F(1,11),rho,gap),(delta,F(0),gap),(delta,F(1,2999),gap),(delta,rho,F(0)),(delta,rho,F(1)),(0.01,rho,gap)):
  try:parameters(d,r,g)
  except ValueError:invalid_rejections+=1
 require(invalid_rejections==7,'Out-of-domain, invalid gap and inexact input rejection')
 result_tests={t['name']:{'hinge_coefficients':t['coefficients'],'source_bank':t['source_bank'],'face_complete_hinge_upper':t['scan']['complete_hinge_upper'],
                         'original_scan_new_dual_count':t['scan']['unique_dual_certificates'],'prefix_available':t['scan']['counts']['prefix_available'],
                         'prefix_bounded':t['scan']['counts']['prefix_bounded'],'fixed_tail_support':supports[t['name']],
                         'transport_error_upper':None,'maximizing_rows':[],'maximizing_witness':None}for t in tests}
 bank_results={};all_keys=set()
 for kind,packed,want in (('heavy',heavy['encoded_rational_duals'],6292),('survival',survival['rational_duals'],2792)):
  bank=exact.decode_dual_bank(packed,7163,56)
  require(len(bank)==want and not(all_keys&set(bank)),'Complete disjoint original dual banks');all_keys.update(bank)
  prices={};digest=sha256();positive_mass=0
  for number,(key,dual)in enumerate(sorted(bank.items()),1):
   inherited,_=partial.price_record(dual,par,caps,budgets,bridge,old,e5,*inventories[0])
   row,raw_witnesses=complete.price_record(dual,inherited,par,caps,budgets,bridge)
   prices[key]=row;positive_mass+=F(dual['equality_duals'][5])>0
   digest.update(json.dumps(encode([key,row]),sort_keys=True,separators=(',',':')).encode())
   for name,tail in supports.items():
    joined=tail_error_from_row(row,par,tail);value=joined['transport_error_upper'];target=result_tests[name]
    if target['transport_error_upper']is None or value>target['transport_error_upper']:
     target['transport_error_upper']=value;target['maximizing_rows']=[{'bank':kind,'dual_key':key}]
     target['maximizing_witness']={'bank':kind,'dual_key':key,'complete_row_record':row,'row_and_tail':joined,'raw_primal_dual_witnesses':raw_witnesses}
    elif value==target['transport_error_upper']:
     target['maximizing_rows'].append({'bank':kind,'dual_key':key})
   if number%1000==0:print(kind+': '+str(number)+'/'+str(want)+' complete rows, four shared-tail consumers.',flush=True)
  encoded=partial.encode_price_bank(prices)
  require(partial.decode_price_bank(encoded)==encode(prices),'Lossless reusable common price table')
  bank_results[kind]={'dual_count':len(bank),'positive_raw_mass_prices':positive_mass,'zero_raw_mass_prices':len(bank)-positive_mass,
                      'complete_price_records_sha256':digest.hexdigest(),'encoded_price_bank':encoded}
  del bank,prices
 require(len(all_keys)==9084,'Every original fixed dual has been repriced once')
 for name,t in result_tests.items():
  require(t['transport_error_upper']is not None,'One complete all-bank error bound per actual objective')
  witness=t['maximizing_witness'];replay=tail_provider.evaluate_row_support(witness['complete_row_record'],par,caps,budgets,bridge,supports[name])
  require(replay['row_and_tail_minus_face_tail_upper']==t['transport_error_upper'],'Independent public231 API consumer at the selected maximum')
  t['nonnegative_transport_allowance']=max(F(0),t['transport_error_upper'])
 return encode({'schema':'erdos7-retained-small-domain-all-bank-transport-v1','source_sha256':pins,'domain':domain,
                'constraint_inventory':counts[0],'dual_count':9084,'direct_raw_support_optimizations':3*9084,
                'invalid_parameter_inputs_rejected':invalid_rejections,'shared_price_banks':bank_results,'tests':result_tests,
                'objective_key_partition':'The original certificates expose per-test newly-used dual counts and maximizing keys, but no complete per-key objective labels. Each test uses a safe residual supremum over both entire banks; no raw dual RHS is maximized across unrelated objectives.',
                'scope':'All9084 original retained dual row residuals and the complete fixed-cut infinite tails, independently for four original225/226 hinge objectives, on the generated certified source rectangle. This is an additive transport allowance for a correctly source-bound original face candidate. It does not by itself transport old pruning/prefix alternatives or prove a complete head,52-cost K comparison,actual-family attainment,Lean result or unrestricted Erdos7 conclusion.'})


def main():
 parser=argparse.ArgumentParser(description=__doc__)
 parser.add_argument('--base',type=Path,default=Path(__file__).resolve().parents[2])
 parser.add_argument('--delta',default=str(DEFAULT_D));parser.add_argument('--rho',default=str(DEFAULT_R));parser.add_argument('--gap',default=str(DEFAULT_G));parser.add_argument('--cut',type=int,default=DEFAULT_CUT)
 modes=parser.add_mutually_exclusive_group();modes.add_argument('--write',action='store_true');modes.add_argument('--check',action='store_true')
 args=parser.parse_args();result=calculate(args.base,args.delta,args.rho,args.gap,args.cut)
 io=module('small_bank_output',args.base/'certificate_io.py')
 if args.write:io.write_certificate_text(args.base/CERTIFICATE,json.dumps(result,indent=2)+'\n')
 else:require(result==json.loads(io.read_artifact_bytes(args.base/CERTIFICATE)),'Exact all-bank small-domain transport certificate')
 for name,test in result['tests'].items():print(name+': additive transport allowance='+str(float(F(test['nonnegative_transport_allowance']))))
 print('PASS:9084 complete row transports, four full-tail residual consumers; complete head/K join remains separate.')


if __name__=='__main__':
 try:main()
 except(ValueError,ArithmeticError,OSError,KeyError,TypeError,json.JSONDecodeError)as error:
  print('FAIL: '+str(error),file=sys.stderr);raise SystemExit(1)
